import fs from "fs";
import path from "path";
import LOGGER from "./logging.js";
/**
 * Loads an asset manifest from a JSON file.
 *
 * @param manifestPath - Path to the manifest file
 * @returns The parsed manifest object, or an empty object if file doesn't exist or has errors
 */
export function loadAssetManifest(manifestPath) {
    if (!fs.existsSync(manifestPath)) {
        LOGGER.info(`Asset manifest file not found: ${manifestPath}. Skipping manifest-based assets.`);
        return {};
    }
    try {
        const content = fs.readFileSync(manifestPath, "utf8");
        const manifest = JSON.parse(content);
        // Validate that the manifest has the expected structure
        for (const [filePath, entry] of Object.entries(manifest)) {
            if (typeof entry !== "object" || typeof entry.assetId !== "string") {
                LOGGER.warn(`Invalid manifest entry for ${filePath}: missing or invalid assetId`);
                delete manifest[filePath];
            }
        }
        LOGGER.info(`Loaded asset manifest with ${Object.keys(manifest).length} entries from ${manifestPath}`);
        return manifest;
    }
    catch (error) {
        LOGGER.error(`Failed to parse asset manifest file ${manifestPath}:`, error);
        return {};
    }
}
/**
 * Gets the asset ID for a given file path from the manifest.
 *
 * @param manifest - The loaded asset manifest
 * @param filePath - Absolute path to the asset file
 * @param assetDirectory - The base assets directory path
 * @returns The asset ID if found in manifest, undefined otherwise
 */
export function getAssetIdFromManifest(manifest, filePath, assetDirectory) {
    // Convert absolute path to relative path from the assets directory
    const relativePath = path.relative(assetDirectory, filePath).replace(/\\/g, "/");
    // Check both the relative path and the filename
    const entry = manifest[relativePath] || manifest[path.basename(filePath)];
    if (entry) {
        LOGGER.info(`Using manifest asset ID for ${relativePath}: rbxassetid://${entry.assetId}`);
        return entry.assetId;
    }
    return undefined;
}
